// Accedemos correctamente al cuerpo del Webhook
const body = $input.item.json.body;
const changeValue = body?.entry?.[0]?.changes?.[0]?.value;

// 1. Si es un estado (entregado/leído), marcamos para ignorar sin romper n8n
if (changeValue && changeValue.statuses) {
    return null;
}

// 2. Si no es un mensaje válido, también marcamos para ignorar
if (!changeValue || !changeValue.messages || !changeValue.messages[0]) {
    return null;
}

const msg = changeValue.messages[0];

// 3. Estructura directa requerida por n8n en este modo
return {
    json: {
        ignore: false,
        type: msg.type, // 'text', 'voice', 'image', 'document', etc.
        from: msg.from,
        wamid: msg.id,
        text: msg.text?.body || null,
        media_id: msg.voice?.id || msg.audio?.id || msg.image?.id || msg.document?.id || null
    }
};

const outputText = $input.item.json.output;
const message = $('Webhook').first().json.body?.entry?.[0]?.changes?.[0]?.value?.messages?.[0];
if (!message?.from || !/^\d+$/.test(String(message.from))) {
  throw new Error('INVALID_WHATSAPP_RECIPIENT: missing sender metadata.');
}
if (typeof outputText !== 'string' || !outputText.trim()) {
  throw new Error('EMPTY_WHATSAPP_REPLY: no response text was generated.');
}
return [{ json: {
  messaging_product: 'whatsapp',
  recipient_type: 'individual',
  to: String(message.from),
  type: 'text',
  text: { body: outputText }
} }];

